mapper.select:
/* selectMasterMdCmMsdsEmailManageList */
SELECT A.SEQ, A.ADD_USER_ID, (SELECT U.USER_NAME_LOC FROM ICOMLUSR U WHERE U.USER_ID = A.ADD_USER_ID) AS ADD_USER_NAME, A.BUYER, (SELECT C.COM_NAME_LOC FROM ICOMCMPY C WHERE C.COM_CODE = A.BUYER) AS BUYER_NAME, A.RECV_USER_NAME, A.RECV_EMAIL, A.REMARK, A.STATUS, A.ADD_DATE, A.CHANGE_DATE, A.CHANGE_USER_ID, (SELECT U.USER_NAME_LOC FROM ICOMLUSR U WHERE U.USER_ID = A.CHANGE_USER_ID) AS CHANGE_USER_NAME FROM KEP_CMC_MAIL_INFO A WHERE 1=1 AND A.STATUS = 'C' AND A.ADD_USER_ID = #{st_user_id}
AND A.BUYER = #{st_buyer_code}
AND UPPER(A.RECV_USER_NAME) LIKE UPPER( '%' || #{st_recv_user_name} || '%')
ORDER BY A.BUYER, A.RECV_USER_NAME, A.ADD_DATE

/*selectMasterMdCmMsdsEmailManageCheck*/

		SELECT	BUYER
		FROM  	KEP_CMC_MAIL_INFO
		WHERE	1=1
		AND		BUYER = #{BUYER}
		AND		RECV_USER_NAME = #{RECV_USER_NAME}
		AND		RECV_EMAIL = #{RECV_EMAIL}
		AND		STATUS = 'C'

mapper.update:
/*deleteMasterMdCmMsdsEmailManage*/

		UPDATE	KEP_CMC_MAIL_INFO
		SET		STATUS = 'D',
				CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'),
				CHANGE_USER_ID = #{st_user_id}
		WHERE	1=1
		AND		STATUS = 'C'
		AND		SEQ = #{SEQ}
